// Spanish → English dictionary with IPA phonetics
// Covers the most common ~500 words to start; will be expanded with the full deck

export interface DictEntry {
  en: string;   // English translation
  ipa: string;  // IPA pronunciation
  pos?: string; // Part of speech: n, v, adj, adv, prep, conj, det, pron
  lemma?: string; // Base/infinitive form
  // Russian-specific. aspect tags the verb as imperfective, perfective, or
  // bi-aspectual. pair points at the partner verb's dict key. note is
  // user-facing copy shown in the conjugation overlay when the relationship
  // is non-obvious (suppletive pairs, semantic shifts, motion-verb pairs).
  aspect?: 'impf' | 'pf' | 'bi';
  pair?: string;
  note?: string;
}

// Lookup helper: strips punctuation, lowercases, tries base forms
export function lookupWord(word: string): DictEntry | null {
  // Preserve hyphens for compound words like check-in
  const clean = word.toLowerCase().replace(/[¿¡.,!?;:"""''()––]/g, '').trim();
  if (!clean) return null;

  // Direct match (compounds like check-in kept intact)
  if (dictionary[clean]) return dictionary[clean];

  // Hyphen fallback: try without hyphens
  if (clean.includes('-')) {
    const noHyphen = clean.replace(/-/g, '');
    if (dictionary[noHyphen]) return dictionary[noHyphen];
  }

  // Strip attached reflexive/object pronouns (acostarme → acostar, dándole → dando)
  const pronounSuffixes = ['melo', 'mela', 'telo', 'tela', 'selo', 'sela', 'noslo', 'nosla', 'melos', 'melas', 'telos', 'telas', 'selos', 'selas', 'me', 'te', 'se', 'nos', 'os', 'le', 'les', 'lo', 'la', 'los', 'las'];
  for (const pronoun of pronounSuffixes) {
    if (clean.endsWith(pronoun) && clean.length > pronoun.length + 2) {
      const stripped = clean.slice(0, -pronoun.length);
      // Restore accent on gerunds (dándole → dando → need to check dándo → dar)
      if (dictionary[stripped]) return dictionary[stripped];
      // Infinitive with pronoun: acostarme → acostar
      if (stripped.endsWith('ar') || stripped.endsWith('er') || stripped.endsWith('ir')) {
        if (dictionary[stripped]) return dictionary[stripped];
        // Try reflexive infinitive: acostar → acostarse
        if (dictionary[stripped + 'se']) return dictionary[stripped + 'se'];
      }
    }
  }

  // Try common verb endings → infinitive approximations
  // This is a simple heuristic; real lemmatization would be better
  const verbEndings = [
    { suffix: 'ando', replace: 'ar' },
    { suffix: 'iendo', replace: 'er' },
    { suffix: 'ando', replace: 'ar' },
    { suffix: 'amos', replace: 'ar' },
    { suffix: 'emos', replace: 'er' },
    { suffix: 'imos', replace: 'ir' },
    { suffix: 'an', replace: 'ar' },
    { suffix: 'en', replace: 'er' },
    { suffix: 'as', replace: 'ar' },
    { suffix: 'es', replace: 'er' },
    { suffix: 'ó', replace: 'ar' },
    { suffix: 'é', replace: 'ar' },
    { suffix: 'aba', replace: 'ar' },
    { suffix: 'ía', replace: 'er' },
  ];

  for (const { suffix, replace } of verbEndings) {
    if (clean.endsWith(suffix)) {
      const stem = clean.slice(0, -suffix.length) + replace;
      if (dictionary[stem]) return dictionary[stem];
    }
  }

  // Try removing plural -s / -es
  if (clean.endsWith('es') && dictionary[clean.slice(0, -2)]) return dictionary[clean.slice(0, -2)];
  if (clean.endsWith('s') && dictionary[clean.slice(0, -1)]) return dictionary[clean.slice(0, -1)];

  // Try removing -a/-o gender suffix
  if (clean.endsWith('a') && dictionary[clean.slice(0, -1) + 'o']) return dictionary[clean.slice(0, -1) + 'o'];
  if (clean.endsWith('o') && dictionary[clean.slice(0, -1) + 'a']) return dictionary[clean.slice(0, -1) + 'a'];

  return null;
}

